 "content": "def transform(grid):
    """Extend each diagonal run of length >= 2 until blocked or the edge."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # A diagonal adjacent pair determines one line orientation. Extend both ends;
    # existing non-background cells (including other colors) stop the ray.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                # Extend backward from first endpoint.
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr, cc = rr - dr, cc - dc
                # Extend forward from second endpoint.
                rr, cc = nr + dr, nc + dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr, cc = rr + dr, cc + dc
    return out

